import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z][a-zA-Z0-9_]{0,63}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against whitelist
        if (!reportType.matches("^(sales|inventory|users|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format strictly
        if (!startDate.matches("^\\d{4}-\\d{2}-\\d{2}$") || 
            !endDate.matches("^\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate sort column if provided
        if (sortCol != null && !SAFE_IDENTIFIER.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        Connection conn = null;
        try {
            conn = getConnection();

            // Build base query with parameterized dates
            StringBuilder sql = new StringBuilder();
            sql.append("SELECT * FROM report_").append(reportType);
            sql.append(" WHERE created_at BETWEEN ? AND ?");

            // Apply custom filter - allows advanced users to add conditions
            if (customFilter != null && !customFilter.isEmpty()) {
                // Basic sanitization: remove comments and semicolons
                String cleaned = customFilter.replaceAll("--", "")
                                            .replaceAll("/\\*.*?\\*/", "")
                                            .replaceAll(";", "");
                sql.append(" AND (").append(cleaned).append(")");
            }

            if (sortCol != null) {
                sql.append(" ORDER BY ").append(sortCol);
            }

            sql.append(" LIMIT 1000");

            PreparedStatement stmt = conn.prepareStatement(sql.toString());
            stmt.setString(1, startDate);
            stmt.setString(2, endDate);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                json.append("\"").append(rs.getString(i)).append("\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
